#ifndef OPTIMIZER_CALL_INTERNAL_H
#define OPTIMIZER_CALL_INTERNAL_H

#include "ir.h"

/**
 * @brief Limits for specialized function variants.
 */
enum {
  // Maximum number of parameters supported for specialized variants
  MAX_PARAMETERS = 8,

  // Maximum number of specialized variants
  MAX_VARIANTS = 16
};

/**
 * @brief A cached specialization identified by callee and bound argument
 * positions.
 */
typedef struct {
  IrFunctionId original;
  IrFunctionId clone;
  unsigned bound;
} CallVariant;

/**
 * @brief Check the growth and control-flow restrictions for straight-line
 * inlining.
 *
 * @param callee Callee to inspect or clone.
 * @return True if straight-line inlining is supported.
 */
bool optimizer_call_can_inline(const IrFunction* callee);

/**
 * @brief Check whether a branching callee fits the CFG inlining budget.
 *
 * @param callee Callee to inspect or clone.
 * @param hot Whether the call site qualifies for the larger loop inlining
 * budget.
 * @return True if the callee meets the CFG inlining limits.
 */
bool optimizer_call_can_inline_cfg(const IrFunction* callee, bool hot);

/**
 * @brief Check that a function meets the specialization size and call
 * restrictions.
 *
 * @param callee Callee to inspect or clone.
 * @return True if the callee meets the specialization limits.
 */
bool optimizer_call_can_specialize(const IrFunction* callee);

/**
 * @brief Replace supported self-tail calls with argument stores and a jump to
 * entry.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function receiving the rewrite.
 */
void optimizer_call_eliminate_tail_calls(Ctx* ctx, IrFunctionId fid);

/**
 * @brief Store an already evaluated argument into its destination slot.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function receiving the rewrite.
 * @param bid Block receiving the emitted instructions.
 * @param slot Stack slot to remap or write.
 * @param value Previously evaluated argument operand.
 */
void optimizer_call_emit_argument_store(Ctx* ctx,
                                        IrFunctionId fid,
                                        IrBlockId bid,
                                        IrStackSlotId slot,
                                        IrOperand value);

/**
 * @brief Insert a straight-line callee at the call and replace its returned
 * value.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function receiving the rewrite.
 * @param bid Block receiving the emitted instructions.
 * @param index Instruction index of the call.
 * @param callee Callee to inspect or clone.
 */
void optimizer_call_inline_call(Ctx* ctx,
                                IrFunctionId fid,
                                IrBlockId bid,
                                size_t index,
                                const IrFunction* callee);

/**
 * @brief Clone a branching callee and route each return to the caller's
 * continuation.
 *
 * @param ctx Compiler context owning the IR.
 * @param fid Function receiving the rewrite.
 * @param bid Block receiving the emitted instructions.
 * @param index Instruction index of the call.
 * @param callee Callee to inspect or clone.
 */
void optimizer_call_inline_cfg(Ctx* ctx,
                               IrFunctionId fid,
                               IrBlockId bid,
                               size_t index,
                               const IrFunction* callee);

/**
 * @brief Construct an unconditional edge to the given block.
 *
 * @param block Destination block ID.
 * @return Unconditional jump terminator targeting the block.
 */
IrBlockTerminator optimizer_call_jump_to(IrBlockId block);

/**
 * @brief Offset an SSA reference while leaving literal operands intact.
 *
 * @param operand Operand to remap in place.
 * @param offset Offset added to the SSA value ID.
 */
void optimizer_call_remap_value(IrOperand* operand, size_t offset);

/**
 * @brief Compare specialized argument literals when looking for a reusable
 * clone.
 *
 * @param a First literal to compare.
 * @param b Second literal to compare.
 * @return True if both literals have the same type and value.
 */
bool optimizer_call_same_constant(IrOperand a, IrOperand b);

/**
 * @brief Clone a function whose selected parameters are initialized from
 * literals on entry.
 *
 * @param ctx Compiler context owning the IR.
 * @param source Function to clone.
 * @param call Call supplying the literal arguments.
 * @param bound Bit mask of parameter positions bound to literals.
 * @return ID of the specialized function.
 */
IrFunctionId optimizer_call_specialize(Ctx* ctx,
                                       IrFunctionId source,
                                       const IrInstruction* call,
                                       unsigned bound);

#endif
